return items.map(i => ({ json: {
  dealId: i.json.id,
  amount: i.json.properties?.amount,
  stage: i.json.properties?.dealstage,
  closeDate: i.json.properties?.closedate
}}));

const crypto = require('crypto');
return items.map(i => {
  const h = crypto.createHash('sha1').update(JSON.stringify(i.json)).digest('hex');
  return { json: { ...i.json, _hash: h } };
});

const out=[];
for (const item of items) {
  const atts = item.binary || {};
  for (const [k,v] of Object.entries(atts)) {
    if ((v.fileName||'').toLowerCase().endsWith('.pdf')) {
      out.push({ json: { subject: item.json.subject, date: item.json.date }, binary: { data: v } });
    }
  }
}
return out;

const hs = new Map();
for (const i of $items('HubSpot')) hs.set((i.json.properties?.email||'').toLowerCase(), i.json);
const dup=[];
for (const m of $items('Mailchimp')) {
  const email = (m.json.email_address||'').toLowerCase();
  if (hs.has(email)) dup.push({json:{email, hubspot:hs.get(email), mailchimp:m.json}});
}
return dup;

const crypto = require('crypto');
const sig = $headers['x-signature'] || '';
const raw = JSON.stringify($json);
const mac = crypto.createHmac('sha256', $env.WEBHOOK_SECRET).update(raw).digest('hex');
if (sig !== mac) throw new Error('bad_signature');
return items;

const lines = items.map(i=>{
  const s=i.json.start?.dateTime||i.json.start?.date;
  return `• ${s} — ${i.json.summary||'(no title)'}`;
});
return [{json:{text:lines.slice(0,20).join('\n')}}];
